def remove_duplicates(lst): 
    unique_list = [] 

    for x in lst: 
        if x not in unique_list: 
            unique_list.append(x) 

    unique_list.sort(reverse=True) # sort in descending order

    return unique_list

def generate_fibonacci_sequence(n): 
    a = 0 
    b = 1
    if n < 0: 
        print("Incorrect input") 
    elif n == 0: 
        return a 
    elif n == 1: 
        return b 
    else: 
        for i in range(2,n): 
            c = a + b 
            a = b 
            b = c 
        return b 

