def fixTypos(text): 
    words = text.split()
    for i in range(len(words)):
        words[i] = spellCheck(words[i])
    return ' '.join(words)

def spellCheck(word):
    dictionary = ["Hello", "Goodbye", "World"]
    minDistance = len(word)
    result = word
    for item in dictionary:
        if distance(word, item) < minDistance:
            minDistance = distance(word, item)
            result = item
    return result

def distance(a, b):
    len_a = len(a)
    len_b = len(b)
    if len_a > len_b: 
        a, b = b, a
        len_a, len_b = len_b, len_a

    current_row = range(len_a + 1) 
    for i in range(1, len_b + 1): 
        previous_row, current_row = current_row, [i] + [0] * len_a 
        for j in range(1, len_a + 1): 
            add, delete, change = previous_row[j] + 1, current_row[j - 1] + 1, previous_row[j - 1] 
            if a[j - 1] != b[i - 1]: 
                change += 1
            current_row[j] = min(add, delete, change) 

    return current_row[len_a]

// Create a function to generate letters 
function generateLetters() {

  // Create an empty string
  let letters = ''; 

  // Generate a random number between 97 - 122
  // This is the ASCII code for a-z
  let randLetter = Math.round(Math.random() * (122 - 97) + 97); 

  // Append the letter to the empty string
  letters += String.fromCharCode(randLetter); 

  // Return the string
  return letters; 
}

